interface Plugin {
  name: string;
  activate(core: EditorCore): void;
}

// The core stays minimal — file editing and rendering only
class EditorCore {
  private plugins: Plugin[] = [];

  register(plugin: Plugin) {
    try {
      plugin.activate(this);
      this.plugins.push(plugin);
    } catch (err) {
      console.error(`Plugin ${plugin.name} failed to load, isolated from core`, err);
    }
  }
}

// Every feature is a plugin — the core doesn't know they exist
class SpellCheckerPlugin implements Plugin {
  name = "spell-checker";
  activate(core: EditorCore) { /* hooks into core's public API only */ }
}

core.register(new SpellCheckerPlugin());
core.register(new LinterPlugin());
